mapper.select:

where r.del_flag = '0'

	AND r.app_id = #{appId}


	AND r.role_id = #{roleId}


	AND r.role_name like concat('%', #{roleName}, '%')


	AND r.status = #{status}


	and date_format(r.create_time,'%Y%m%d') >= date_format(#{params.beginTime},'%Y%m%d')


	and date_format(r.create_time,'%Y%m%d') <= date_format(#{params.endTime},'%Y%m%d')

order by r.role_sort


 where r.role_name=#{roleName} and r.del_flag = '0'

	AND r.app_id = #{appId}

 limit 1


 where r.role_key=#{roleKey} and r.del_flag = '0'

	AND r.app_id = #{appId}

 limit 1

mapper.update:
update vpn_role
app_id = #{appId}, role_name = #{roleName}, role_key = #{roleKey}, role_sort = #{roleSort}, menu_check_strictly = #{menuCheckStrictly}, status = #{status}, remark = #{remark}, dingtalk_enabled = #{dingtalkEnabled}, dingtalk_access_token = #{dingtalkAccessToken}, dingtalk_secret = #{dingtalkSecret}, dingtalk_webhook_url = #{dingtalkWebhookUrl}, update_by = #{updateBy}, update_time = sysdate()
where role_id = #{roleId}
